import React, { useState } from "react";

function App() {
  const [resultados, setResultados] = useState(null);

  const subirArchivos = async (e) => {
    const files = e.target.files;
    const formData = new FormData();
    for (let f of files) formData.append("files", f);

    const res = await fetch("http://localhost:4000/upload", {
      method: "POST",
      body: formData
    });

    const data = await res.json();
    setResultados(data);
  };

  return (
    <div style={{ padding: 40, fontFamily: "Arial" }}>
      <h1>Calculadora IVA XML CR</h1>
      <p>Carga tus archivos XML de factura electrónica</p>

      <input type="file" multiple onChange={subirArchivos} accept=".xml" />

      {resultados && (
        <div style={{ marginTop: 30 }}>
          <h2>Resultados:</h2>
          <ul>
            <li><strong>IVA 0%:</strong> ₡{resultados["0%"].toLocaleString()}</li>
            <li><strong>IVA 1%:</strong> ₡{resultados["1%"].toLocaleString()}</li>
            <li><strong>IVA 2%:</strong> ₡{resultados["2%"].toLocaleString()}</li>
            <li><strong>IVA 13%:</strong> ₡{resultados["13%"].toLocaleString()}</li>
          </ul>
        </div>
      )}
    </div>
  );
}

export default App;
